n=int(input());iv=[]
for _ in range(n):
    l,r=map(int,input().split());iv.append((l,r))
iv.sort()
out=[]
for l,r in iv:
    if out and l<=out[-1][1]: out[-1][1]=max(out[-1][1],r)
    else: out.append([l,r])
print("\n".join(f"{l} {r}" for l,r in out))

